        // Use common assignForReview function for post-processing
        const assignResult = getTracker().assignForReview(ticketKey, initiatorId, wipLabel);

        if (!assignResult.success) {
            return assignResult;
        }

        const successCount = (updateResults.descriptionUpdated ? 1 : 0) + 
                           (updateResults.diagramUpdated ? 1 : 0) + 
                           (updateResults.labelAdded ? 1 : 0);

        return {
            success: true,
            message: `Ticket ${ticketKey} enhanced, assigned, moved to In Review. Updates: ${successCount}/3 successful`,
            enhancementData: enhancementData,
            updateResults: updateResults
        };

    } catch (error) {
        console.error("❌ Error:", error);

        return {
            success: false,
            error: error.toString()
        };
    }
}


if (typeof module !== "undefined" && module.exports) {
    module.exports = { action };
}

/**
 * Create Questions and Assign For Review Post-Action
 * Reads AI-generated outputs/questions.json, creates question subtasks in Jira,
 * labels the parent ticket, and assigns it for review.
 *
 * questions.json format:
 * [
 *   {
 *     "summary": "Clarify requirements",          // [Q] prefix added automatically if missing
 *     "priority": "High",
